marshal:
switch pk.TextType {
case TextTypeChat, TextTypeWhisper, TextTypeAnnouncement:
	io.String(&pk.SourceName)
	if len(pk.SourceName) > 256 {
		io.InvalidValue(pk.SourceName, "source name", "string too long")
	}
	io.String(&pk.Message)
case TextTypeRaw, TextTypeTip, TextTypeSystem, TextTypeObject, TextTypeObjectWhisper, TextTypeObjectAnnouncement:
	io.String(&pk.Message)
case TextTypeTranslation, TextTypePopup, TextTypeJukeboxPopup:
	io.String(&pk.Message)
	protocol.FuncSlice(io, &pk.Parameters, io.String)
	if len(pk.Parameters) > 4 {
		io.InvalidValue(pk.Parameters, "parameters", "too many parameters")
	}
}

if len(pk.Message) == 0 {
	io.InvalidValue(pk.Message, "message", "string cannot be empty")
}

if len(pk.PlatformChatID) > 256 {
	io.InvalidValue(pk.PlatformChatID, "platform chat ID", "string too long")
}

if filteredMessage, ok := pk.FilteredMessage.Value(); ok && len(filteredMessage) > 65536 {
	io.InvalidValue(filteredMessage, "filtered message", "string too long")
}

if !hasType {
	io.InvalidValue(hasType, "InventoryTransaction transaction type", "expected presence bool to be true")
}

if !hasActions {
	io.InvalidValue(hasActions, "InventoryTransaction actions", "expected presence bool to be true")
}

if val, ok := swingSource.Value(); ok {
	swingSourceFromString(io, &pk.SwingSource, val)
}

if pk.SubChunkCount > 64 {
	io.InvalidValue(pk.SubChunkCount, "level chunk sub-chunk count", "must not exceed 64")
}

if pk.Block {
	io.BlockPos(&pk.Position)
	io.Varuint32(&pk.Mode)
	io.Bool(&pk.NeedsRedstone)
	io.Bool(&pk.Conditional)
} else {
	io.ActorRuntimeID(&pk.MinecartEntityRuntimeID)
}

if pk.ActionType != ScoreboardIdentityActionRegister && pk.ActionType != ScoreboardIdentityActionClear {
	io.UnknownEnumOption(pk.ActionType, "scoreboard identity action type")
}

if count > 9216 {
	io.InvalidValue(count, "savedChunks", "saved chunks exceeds maximum length of 9216 chunk positions")
}

if pk.Type >= uint32(len(names)) {
	io.UnknownEnumOption(pk.Type, "entity override type")
	return
}
